-- Month-to-month persistence of CSP and technician timeout rates; CSP lists for discovery calls (ids only).
-- Append to base.sql (it ends inside a WITH list, at CTE b) and run the two together.
, c AS (SELECT csp_id::STRING id, COUNT_IF(mon='Oct') on_, COUNT_IF(mon='Oct' AND grp='timeout') ot, COUNT_IF(mon='Nov') nn, COUNT_IF(mon='Nov' AND grp='timeout') nt FROM b GROUP BY 1),
t AS (SELECT executor_id::STRING id, COUNT_IF(mon='Oct') on_, COUNT_IF(mon='Oct' AND grp='timeout') ot, COUNT_IF(mon='Nov') nn, COUNT_IF(mon='Nov' AND grp='timeout') nt FROM b GROUP BY 1)
SELECT 'A CSPs by October timeout rate (10+ Oct tasks): CSPs / Oct tasks / Oct timeouts / Nov tasks / Nov timeouts' sec, CASE WHEN ot=0 THEN '1: 0%' WHEN ot/on_<0.10 THEN '2: under 10%' WHEN ot/on_<0.25 THEN '3: 10-25%' ELSE '4: 25%+' END k, COUNT(*)::STRING a, SUM(on_)::STRING b, SUM(ot)::STRING c, SUM(nn)::STRING d, SUM(nt)::STRING e FROM c WHERE on_>=10 GROUP BY 1,2
UNION ALL SELECT 'B technicians by October timeout rate (10+ Oct tasks): technicians / Oct tasks / Oct timeouts / Nov tasks / Nov timeouts', CASE WHEN ot=0 THEN '1: 0%' WHEN ot/on_<0.10 THEN '2: under 10%' WHEN ot/on_<0.25 THEN '3: 10-25%' ELSE '4: 25%+' END, COUNT(*)::STRING, SUM(on_)::STRING, SUM(ot)::STRING, SUM(nn)::STRING, SUM(nt)::STRING FROM t WHERE on_>=10 GROUP BY 1,2
UNION ALL (SELECT 'C CSPs with the most timeouts (both months): csp / Oct tasks / Oct timeouts / Nov tasks / Nov timeouts', LPAD(ROW_NUMBER() OVER (ORDER BY ot+nt DESC, on_+nn DESC),2,'0'), id, on_::STRING, ot::STRING, nn::STRING, nt::STRING FROM c QUALIFY ROW_NUMBER() OVER (ORDER BY ot+nt DESC, on_+nn DESC) <= 15)
UNION ALL (SELECT 'D busy CSPs with almost no timeouts: csp / Oct tasks / Oct timeouts / Nov tasks / Nov timeouts', LPAD(ROW_NUMBER() OVER (ORDER BY on_+nn DESC),2,'0'), id, on_::STRING, ot::STRING, nn::STRING, nt::STRING FROM c WHERE ot+nt<=1 QUALIFY ROW_NUMBER() OVER (ORDER BY on_+nn DESC) <= 8)
UNION ALL (SELECT 'E CSPs with the highest timeout rate (20+ tasks both months): csp / Oct tasks / Oct timeouts / Nov tasks / Nov timeouts', LPAD(ROW_NUMBER() OVER (ORDER BY (ot+nt)/(on_+nn) DESC),2,'0'), id, on_::STRING, ot::STRING, nn::STRING, nt::STRING FROM c WHERE on_+nn>=20 QUALIFY ROW_NUMBER() OVER (ORDER BY (ot+nt)/(on_+nn) DESC) <= 10)
ORDER BY 1,2
